/**
 * secrets-veil must never return a tool result unmasked, even when the mod
 * never saw session.start (enabled or hot-reloaded mid-session). This file
 * runs in its own module instance (vitest isolates per file), so `table`
 * starts null exactly as it does in that window. Each test registers fresh
 * hooks but shares the module, so the no-session case runs first.
 */

import { describe, test, expect } from "vitest";
import { register, MAX_MASK_CHARS, MAX_MASK_MS, WITHHELD } from "../hooks/register.js";
import { vi } from "vitest";

type RegisteredHook = (...args: unknown[]) => unknown;

// A fake GitHub token shape, assembled at runtime so no token-shaped literal
// sits in the source: the ghp_ prefix plus 36 filler characters.
const FAKE_GH = "gh" + "p_" + "Zq8Lm3Rt7Vx2Kp9Nw4Hy6Bc1Df5Gj0Sa8Ue3";

/** Synthetic named value: no vendor shape, low entropy, so only the named path masks it. */
const SYNTHETIC = "veiltest-synthetic-value-42";

/** .catch handlers the module registered, by event. */
const catches = new Map<string, (...args: unknown[]) => unknown>();

function hooksOf(): Map<string, RegisteredHook> {
  const hooks = new Map<string, RegisteredHook>();
  register((event: string, hook: unknown) => {
    hooks.set(event, hook as RegisteredHook);
    // The engine's registration: on() returns an object that takes one .catch.
    return { catch: (handler: (...args: unknown[]) => unknown) => catches.set(event, handler) };
  }, {});
  return hooks;
}

function fake$(env: Record<string, string> | "throws"): unknown {
  return {
    env: {
      get: async (name: string): Promise<string | undefined> => {
        if (env === "throws") throw new Error(`env.get(${name}) refused`);
        return env[name];
      },
    },
    ui: {
      notice: async (): Promise<void> => undefined,
      toast: async (): Promise<void> => undefined,
      status: async (): Promise<void> => undefined,
      log: async (): Promise<void> => undefined,
    },
  };
}

const next = (result: unknown) => async (): Promise<unknown> => result;

describe("fail closed when session.start never ran", () => {
  test("a planted ghp_ token and a named value come out masked with no session.start", async () => {
    const hooks = hooksOf();
    const out = await hooks.get("tool.call")!(
      fake$({ GITHUB_TOKEN: SYNTHETIC }),
      { tool: "Bash", args: {} },
      next({ result: { stdout: `FAKE_TOKEN=${FAKE_GH}\nNAMED=${SYNTHETIC}\n` } })
    );
    const text = JSON.stringify(out);
    expect(text).not.toContain(FAKE_GH);
    // The lazy arm read the named variables too, not only the shapes.
    expect(text).not.toContain(SYNTHETIC);
    expect(text).toContain("•".repeat(8));
  });
});

describe("fail closed when masking itself throws", () => {
  test("a result that cannot be walked is withheld with deny, never passed through", async () => {
    const hooks = hooksOf();
    const hostile = {
      get stdout(): string {
        throw new Error("unreadable field");
      },
    };
    const out = (await hooks.get("tool.call")!(fake$({}), { tool: "Bash", args: {} }, next({ result: hostile }))) as {
      deny?: string;
      result?: unknown;
    };
    expect(out.result).toBeUndefined();
    expect(out.deny).toContain("withheld rather than shown unmasked");
  });
});

describe("nothing fails open after next(e) ran", () => {
  test("tool.call registers a .catch that answers deny (the runtime's throw and overrun path)", () => {
    hooksOf();
    const handler = catches.get("tool.call");
    expect(handler).toBeTypeOf("function");
    expect(handler!()).toEqual({ deny: WITHHELD });
  });

  test("a throw where the old code had no guard (reading the event's tool name) is a deny", async () => {
    const hooks = hooksOf();
    const hostileEvent = {
      args: {},
      get tool(): string {
        throw new Error("event field unreadable");
      },
    };
    const out = (await hooks.get("tool.call")!(
      fake$({}),
      hostileEvent,
      next({ result: { stdout: `FAKE_TOKEN=${FAKE_GH}\n` } })
    )) as { deny?: string; result?: unknown };
    expect(out).toEqual({ deny: WITHHELD });
  });

  test("a result over the size cap is withheld", async () => {
    const hooks = hooksOf();
    // Many ordinary lines, none large on its own: only the running total
    // crosses the cap, so this isolates the size guard.
    const line = "ordinary output line ".repeat(50);
    const lines = Array.from({ length: Math.ceil(MAX_MASK_CHARS / line.length) + 1 }, () => line);
    const out = (await hooks.get("tool.call")!(fake$({}), { tool: "Bash", args: {} }, next({ result: { lines } }))) as {
      deny?: string;
    };
    expect(out).toEqual({ deny: WITHHELD });
  });

  test("masking that runs past its time cap is withheld (forced overrun)", async () => {
    const hooks = hooksOf();
    const realNow = Date.now;
    let calls = 0;
    // The first read sets the deadline; every later read is past it.
    const spy = vi.spyOn(Date, "now").mockImplementation(() => (calls++ === 0 ? realNow() : realNow() + MAX_MASK_MS + 1));
    try {
      const out = (await hooks.get("tool.call")!(
        fake$({}),
        { tool: "Bash", args: {} },
        next({ result: { stdout: `FAKE_TOKEN=${FAKE_GH}\n` } })
      )) as { deny?: string };
      expect(out).toEqual({ deny: WITHHELD });
    } finally {
      spy.mockRestore();
    }
  });

  test("a Buffer result is withheld, never rebuilt as a plain object", async () => {
    const hooks = hooksOf();
    const out = (await hooks.get("tool.call")!(
      fake$({}),
      { tool: "Read", args: {} },
      next({ result: Buffer.from(`FAKE_TOKEN=${FAKE_GH}`) })
    )) as { deny?: string };
    expect(out).toEqual({ deny: WITHHELD });
  });

  test("a Map inside a result is withheld", async () => {
    const hooks = hooksOf();
    const out = (await hooks.get("tool.call")!(
      fake$({}),
      { tool: "Read", args: {} },
      next({ result: { meta: new Map([["k", FAKE_GH]]) } })
    )) as { deny?: string };
    expect(out).toEqual({ deny: WITHHELD });
  });
});
